import { formatEuros } from './money.js';
import { invoiceTotals } from './invoices.js';

/**
 * Render a plain-text invoice.
 * @param {{ number?: string, customerId: string, customerName: string, issueDate: string, status: string, lines: Array<{ sku: string, name: string, qty: number, unitPrice: number, vatRate: number, discountPercent: number }> }} invoice
 * @returns {string}
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // Invoice number or DRAFT
  const invoiceNumber = invoice.number ?? 'DRAFT';
  lines.push(invoiceNumber);

  // Customer name
  lines.push(invoice.customerName);

  // Invoice lines
  for (const line of invoice.lines) {
    const lineAmount = line.qty * line.unitPrice;
    const qtyStr = String(line.qty);
    const priceStr = formatEuros(line.unitPrice);
    const totalStr = formatEuros(lineAmount);
    lines.push(`${qtyStr}x ${line.name} @ ${priceStr} = ${totalStr}`);
  }

  // Calculate totals
  const totals = invoiceTotals(invoice);

  // Show VAT line if there's any VAT
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Total line
  lines.push(`Total: ${formatEuros(totals.total)}`);

  return lines.join('\n');
}

