import test from 'node:test';
import assert from 'node:assert/strict';
import { renderInvoiceText } from '../src/render.js';

test('renderInvoiceText shows DRAFT for unsigned invoice', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Northwind Studio',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.startsWith('DRAFT\n'));
});

test('renderInvoiceText shows invoice number when present', () => {
  const invoice = {
    number: 'INV-2026-0001',
    customerId: 'C-001',
    customerName: 'Northwind Studio',
    issueDate: '2026-10-07',
    status: 'issued',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.startsWith('INV-2026-0001\n'));
});

test('renderInvoiceText includes customer name', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Northwind Studio',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[1], 'Northwind Studio');
});

test('renderInvoiceText shows each line item', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Northwind Studio',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
      { sku: 'LOGO-PACK', name: 'Logo package', qty: 1, unitPrice: 120000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines.length, 6); // number, customer, 2 items, VAT, total
  assert.ok(lines[2].includes('5x Development (hour)'));
  assert.ok(lines[2].includes('€95.00')); // 9500 cents = €95.00
  assert.ok(lines[2].includes('€475.00')); // 5 * 9500 = 47500 cents = €475.00
});

test('renderInvoiceText formats currency correctly', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'PRINT-A4', name: 'Printed flyer A4 (each)', qty: 100, unitPrice: 37, vatRate: 9 },
    ],
  };
  const text = renderInvoiceText(invoice);
  // 100 * 37 cents = 3700 cents = €37.00
  assert.ok(text.includes('€0.37')); // unit price
  assert.ok(text.includes('€37.00')); // line total
});

test('renderInvoiceText totals all line items', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Northwind Studio',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21, discountPercent: 0 },
      { sku: 'DES-HOUR', name: 'Design work (hour)', qty: 3, unitPrice: 8500, vatRate: 21, discountPercent: 0 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  const lastLine = lines[lines.length - 1];
  // Subtotal: 5*9500 + 3*8500 = 73000
  // VAT: 73000 * 21% = 15330
  // Total: 73000 + 15330 = 88330 cents = €883.30
  assert.ok(lastLine.startsWith('Total: €883.30'));
});

test('renderInvoiceText with empty lines array', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Northwind Studio',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines[lines.length - 1], 'Total: €0.00');
});

test('renderInvoiceText preserves line breaks', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Northwind Studio',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 5, unitPrice: 9500, vatRate: 21 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  assert.equal(lines.length, 4); // number, customer, 1 item, total
});

test('renderInvoiceText shows quantity and product name for each line', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Blue Fern Bakery',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'ICON-SET', name: 'Icon set (24 icons)', qty: 2, unitPrice: 980, vatRate: 21, discountPercent: 0 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(text.includes('2x Icon set (24 icons)'));
});

test('renderInvoiceText shows VAT when invoice has VAT', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 0 },
    ],
  };
  const text = renderInvoiceText(invoice);
  // 100*1000=100000, VAT 21%=21000
  assert.ok(text.includes('VAT: €210.00'));
});

test('renderInvoiceText does not show VAT when invoice has no VAT', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'WORKSHOP-DAY', name: 'Brand workshop (day, VAT exempt)', qty: 1, unitPrice: 60000, vatRate: 0, discountPercent: 0 },
    ],
  };
  const text = renderInvoiceText(invoice);
  assert.ok(!text.includes('VAT:'));
  assert.ok(text.includes('Total: €600.00'));
});

test('renderInvoiceText shows VAT on separate line', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
    ],
  };
  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');
  // Should have: number, customer, item line, VAT line, total line
  assert.ok(lines[lines.length - 2].startsWith('VAT:'));
  assert.ok(lines[lines.length - 1].startsWith('Total:'));
});

test('renderInvoiceText total includes VAT in calculation', () => {
  const invoice = {
    customerId: 'C-001',
    customerName: 'Test Customer',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [
      { sku: 'DEV-HOUR', name: 'Development (hour)', qty: 100, unitPrice: 1000, vatRate: 21, discountPercent: 10 },
    ],
  };
  const text = renderInvoiceText(invoice);
  // Subtotal: 100000, Discount: 10000, Amount after discount: 90000
  // VAT: 21% of 90000 = 18900
  // Total: 100000 - 10000 + 18900 = 108900
  assert.ok(text.includes('Total: €1,089.00'));
});

